"use client";

import React, { useEffect, useRef, useState } from "react";
import { api } from "@/lib/api";
import { useCurrentUser } from "@/hooks/use-current-user";
import { Conversation, Message } from "@/types";

export default function MessagesPage() {
  const { currentUser, loading } = useCurrentUser();
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selected, setSelected] = useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);
  const bottomRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!currentUser) return;
    (async () => {
      const convos = await api.getConversations(currentUser.tenantId);
      setConversations(convos);
      if (convos.length > 0) {
        setSelected(convos[0]);
      }
    })();
  }, [currentUser]);

  // load messages when selected changes
  useEffect(() => {
    if (!currentUser || !selected) return;
    (async () => {
      const msgs = await api.getMessagesForConversation(
        currentUser.tenantId,
        selected.id
      );
      setMessages(msgs);
      setTimeout(() => {
        bottomRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 50);
    })();
  }, [currentUser, selected]);

  async function handleSend(e: React.FormEvent) {
    e.preventDefault();
    if (!input.trim() || !currentUser || !selected) return;
    setSending(true);
    await api.simulateInboundSms(
      currentUser.tenantId,
      selected.id,
      input.trim()
    );
    const msgs = await api.getMessagesForConversation(
      currentUser.tenantId,
      selected.id
    );
    setMessages(msgs);
    setInput("");
    setSending(false);
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="h-8 w-8 rounded-full border-2 border-brand-primary border-t-transparent animate-spin" />
      </div>
    );
  }

  return (
    <div className="flex h-[calc(100vh-7rem)] bg-dark-card rounded-xl border border-slate-800/40 overflow-hidden">
      {/* left list */}
      <div className="w-72 border-r border-slate-800/40 bg-slate-950/40">
        <div className="p-4">
          <h2 className="text-lg font-semibold text-white">Conversations</h2>
        </div>
        <div className="overflow-y-auto h-full">
          {conversations.map((c) => (
            <button
              key={c.id}
              onClick={() => setSelected(c)}
              className={`w-full text-left px-4 py-3 flex gap-3 hover:bg-slate-800/40 ${
                selected?.id === c.id ? "bg-slate-800/60" : ""
              }`}
            >
              <div className="w-10 h-10 rounded-full bg-brand-primary flex items-center justify-center text-white text-sm">
                {c.leadName?.slice(0, 2).toUpperCase()}
              </div>
              <div className="flex-1">
                <p className="text-sm text-white">{c.leadName}</p>
                <p className="text-xs text-dark-text-secondary line-clamp-1">
                  {c.lastMessage}
                </p>
              </div>
            </button>
          ))}
          {conversations.length === 0 && (
            <p className="text-xs text-dark-text-secondary px-4 pb-6">
              No conversations yet.
            </p>
          )}
        </div>
      </div>

      {/* right chat */}
      <div className="flex-1 flex flex-col">
        <div className="p-4 border-b border-slate-800/40">
          <p className="text-sm text-dark-text-secondary">
            {selected ? "Chat with" : "No conversation selected"}
          </p>
          <h2 className="text-lg font-semibold text-white">
            {selected?.leadName || "—"}
          </h2>
        </div>
        <div className="flex-1 overflow-y-auto p-6 space-y-3">
          {messages.map((m) => (
            <div
              key={m.id}
              className={`flex ${
                m.from === "agent" ? "justify-end" : "justify-start"
              }`}
            >
              <div
                className={`max-w-sm px-4 py-2 rounded-2xl text-sm ${
                  m.from === "agent"
                    ? "bg-brand-primary text-white rounded-br-none"
                    : "bg-slate-800 text-white/90 rounded-bl-none"
                }`}
              >
                {m.body}
              </div>
            </div>
          ))}
          <div ref={bottomRef} />
        </div>
        <form onSubmit={handleSend} className="p-4 border-t border-slate-800/40">
          <div className="flex gap-3">
            <label htmlFor="message" className="sr-only">
              Message
            </label>
            <input
              id="message"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              className="flex-1 bg-slate-900/50 border border-slate-700 rounded-md px-3 py-2 text-white outline-none focus:ring-2 focus:ring-brand-primary"
              placeholder="Write a message to simulate SMS..."
            />
            <button
              type="submit"
              disabled={sending || !selected}
              className="bg-brand-primary hover:bg-brand-secondary px-4 py-2 rounded-md text-white text-sm disabled:opacity-60"
            >
              {sending ? "Sending..." : "Send"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
